SELECT id, name FROM students
WHERE dept_id IN (SELECT id FROM departments WHERE name = '数学')
ORDER BY id;

SELECT id, name FROM students
WHERE score > (SELECT AVG(score) FROM students)
ORDER BY id;

SELECT d.id, d.name FROM departments AS d
WHERE EXISTS (SELECT 1 FROM students AS s WHERE s.dept_id = d.id)
ORDER BY d.id;

SELECT id, score FROM students
WHERE score > ANY (SELECT score FROM students WHERE id IN (2,4))
ORDER BY id;

SELECT id, score FROM students
WHERE score > ALL (SELECT score FROM students WHERE id IN (2,4))
ORDER BY id;

SELECT s.id, s.dept_id FROM students AS s
LEFT JOIN departments AS d ON s.dept_id = d.id
WHERE d.id IS NULL ORDER BY s.id;
